// Interrupteur d'affichage debug
const DEBUG_ENABLED = false;   // <-- mets true pour voir les logs, false pour ne rien afficher
// --------- FILTRE D'AFFICHAGE DES ZONES (HARD-CODE) ----------
// -> C'est ici que tu choisis les zones qui t'intéressent
// Exemple 1 : par numéro de zone
const ZONES_DEBUG = {
    by: "numero",          // "numero" | "planningId" | "nom" | "index"
    values: [10],           // <- liste de numéros de zone à afficher
    regex: null            // ex. "Bureau|Salle" si by="nom"
};

/*
// Exemple 2 : par nom avec regex (dé-commente si tu préfères)
const ZONES_DEBUG = {
    by: "nom",
    values: null,
    regex: "Bureau|Salle"  // tous les noms contenant Bureau ou Salle
};
*/

//Fct calcul Pilotages & Consignes
let params = global.get("params") || {};
let meteo = global.get("meteo") || {};
let plannings = global.get("plannings") || [];
let events = global.get("events") || [];
let zones = global.get("zones") || [];

// Helper pour forcer en Number quand c'est possible
function n(val) {
    if (val === null || val === undefined) return val;
    if (typeof val === "number") return val;
    if (typeof val === "string") {
        const num = Number(val.trim());
        if (!Number.isNaN(num)) return num;
    }
    return val; // on laisse tel quel (ex: chaînes, labels…)
}

// Variables internes
let now = new Date();
let currentHour = now.getHours();
let currentMinute = now.getMinutes();
let currentTime = currentHour * 60 + currentMinute; // Convertit l'heure actuelle en minutes
let dayOfWeek = now.getDay(); // 0 = Dimanche, 1 = Lundi, ..., 6 = Samedi

let planningZone = {};
let dayKeyToday = "day1";
let dayKeyYesterday = "day0";
let dayKeyTwoDays = "day6";
let indexPlannEteHiver = determinerPeriode(params);
let temp = [];

// Paramètres numériques utiles (évite les strings dans les calculs)
const seuilBasModeCLIM    = n(params.seuilbasModeCLIM);
const seuilHautModeCLIM   = n(params.seuilHautModeCLIM);
const consigneHorsGel     = n(params.consigneHorsGel);
const tempNonChauffe      = n(params.tempNonChauffe);
const tempNonClim         = n(params.tempNonClim);
const hysteresisRegulTOR  = n(params.hysteresisRegulTOR);
const hysteresisRegulCLIM = n(params.hysteresisRegulCLIM);
const gestionModeCLIM     = n(params.gestionModeCLIM);
const tempext             = n(meteo.tempext);

for (let x = 0; x < zones.length; x++) {
    let dataZones = {
        "temp": zones[x].data.temp,
        "humidity": zones[x].data.humidity,
        "light": zones[x].data.light,
        "presence": zones[x].data.presence,
        "statusAllumage": zones[x].data.statusAllumage,
        "statusConsigne": zones[x].data.statusConsigne,
        "statusMode": zones[x].data.statusMode,
        "pilotageClimZone": zones[x].data.pilotageClimZone,
        "consigneClimZone": zones[x].data.consigneClimZone,
        "modeClimZone": zones[x].data.modeClimZone,
        "pilotageTorZone": zones[x].data.pilotageTorZone,
        "consigneTorZone": zones[x].data.consigneTorZone
    };

    // --- NORMALISATION NUMÉRIQUE SUR LA ZONE ---
    if (dataZones.temp && dataZones.temp.hasOwnProperty("value")) {
        dataZones.temp.value = n(dataZones.temp.value);
    }
    if (dataZones.humidity && dataZones.humidity.hasOwnProperty("value")) {
        dataZones.humidity.value = n(dataZones.humidity.value);
    }
    if (dataZones.light && dataZones.light.hasOwnProperty("value")) {
        dataZones.light.value = n(dataZones.light.value);
    }
    if (dataZones.presence && dataZones.presence.hasOwnProperty("value")) {
        dataZones.presence.value = n(dataZones.presence.value);
        if (dataZones.presence.lastPresenceDetectedTimestamp !== undefined) {
            dataZones.presence.lastPresenceDetectedTimestamp = n(dataZones.presence.lastPresenceDetectedTimestamp);
        }
        if (dataZones.presence.timestamp !== undefined) {
            dataZones.presence.timestamp = n(dataZones.presence.timestamp);
        }
    }
    if (dataZones.statusAllumage && dataZones.statusAllumage.hasOwnProperty("value")) {
        dataZones.statusAllumage.value = n(dataZones.statusAllumage.value);
    }
    if (dataZones.statusConsigne && dataZones.statusConsigne.hasOwnProperty("value")) {
        dataZones.statusConsigne.value = n(dataZones.statusConsigne.value);
    }
    if (dataZones.statusMode && dataZones.statusMode.hasOwnProperty("value")) {
        dataZones.statusMode.value = n(dataZones.statusMode.value);
    }

    dataZones.pilotageClimZone = n(dataZones.pilotageClimZone);
    dataZones.consigneClimZone = n(dataZones.consigneClimZone);
    dataZones.modeClimZone     = n(dataZones.modeClimZone);
    dataZones.pilotageTorZone  = n(dataZones.pilotageTorZone);
    dataZones.consigneTorZone  = n(dataZones.consigneTorZone);

    // On récupère les infos du planning
    for (let y = 0; y < plannings.length; y++) {
        if (plannings[y].id == zones[x].planningId) {
            planningZone = plannings[y];
        }
    }
    var consignesArray = [
        [
            Number(planningZone.consigneHiverConfort),
            Number(planningZone.consigneHiverReduit),
            Number(planningZone.consigneHiverAbsence)
        ],
        [
            Number(planningZone.consigneEteConfort),
            Number(planningZone.consigneEteReduit),
            Number(planningZone.consigneEteAbsence)
        ]
    ];

    // **************************** ETAT DE LA PIECE (Confort / Réduit / Absence) **************************** //
    // On récupère le jour et l'heure actuel
    dayKeyToday = "day" + dayOfWeek;
    if (dayOfWeek == 0) {
        dayKeyYesterday = "day" + 6;
    } else {
        dayKeyYesterday = "day" + (dayOfWeek - 1);
    }
    var todaySchedule = planningZone[dayKeyToday];
    var yesterdaySchedule = planningZone[dayKeyYesterday];

    // Parser les chaînes pour aujourd'hui et hier
    var yesterdayEvents = parseSchedule(yesterdaySchedule, -1); // Décale les horaires d'hier d'une journée
    var todayEvents = parseSchedule(todaySchedule, 0);

    // Déterminer l'état en fonction de l'heure actuelle
    var currentState = null;
    for (let i = 0; i < todayEvents.length; i++) {
        let currentEvent = todayEvents[i];
        let nextEvent = todayEvents[i + 1] || { time: Infinity, state: currentEvent.state };
        if (currentTime >= currentEvent.time && currentTime < nextEvent.time) {
            currentState = currentEvent.state;
            break;
        }
    }

    // Si aucun état n'est trouvé, utilisez la dernière valeur du jour précédent
    if (currentState === null) {
        if (yesterdayEvents == null || yesterdayEvents == undefined || yesterdayEvents == []) {
            if (dayOfWeek == 0) {
                dayKeyTwoDays = "day" + 5;
            } else if (dayOfWeek == 1) {
                dayKeyTwoDays = "day" + 6;
            } else {
                dayKeyTwoDays = "day" + (dayOfWeek - 2);
            }
            let twoDaysEvents = parseSchedule(planningZone[dayKeyTwoDays], -2);
            if (twoDaysEvents == null || twoDaysEvents == undefined || twoDaysEvents == []) {
                currentState = 2;
            } else {
                currentState = twoDaysEvents[twoDaysEvents.length - 1].state;
            }
        } else {
            if (yesterdayEvents.length > 0 && "state" in yesterdayEvents[yesterdayEvents.length - 1]) {
                currentState = yesterdayEvents[yesterdayEvents.length - 1].state;
            }
            else {
                currentState = 2;
            }
        }
    }

    // On récupère les évènements actifs
    const zoneId = n(zones[x].id);
    var activeEvents = events.filter(event =>
        isEventActive(event, now) &&
        (event.zoneId === undefined || event.zoneId === null || n(event.zoneId) === zoneId)
    );
    let forcageArretEvent = 0;
    if (activeEvents.length > 0) {
        let valueEvent = Number(activeEvents[0].value);
        // valueEvent : 0=Auto / 1=Confort / 2=Réduit / 3=Absence / 4=Arret
        if (valueEvent >= 1 && valueEvent <= 3) {
            currentState = valueEvent - 1;
        }
        else if (valueEvent == 4) { // cas où on doit arréter le pilotage
            forcageArretEvent = 1;
        }
    }

    // on vérifie que la valeur currentState est bien entre 0 et 2
    if (currentState > 2) {
        currentState == 2;
        node.warn("Attention erreur dans les valeurs du plannings. Le satut de la pièce " + zones[x].numero + " à été mis à 'Absent'");
    }
    else if (currentState < 0) {
        currentState == 0;
        node.warn("Attention erreur dans les valeurs du plannings. Le satut de la pièce " + zones[x].numero + " à été mis à 'Confort'");
    }

    // **************************** MODE CLIM **************************** //
    // On récupère le mode actuel (0=Auto / 1=Heat / 2=Cool / 3=Fan)
    var actualMode = dataZones.statusMode.value;
    if (gestionModeCLIM == 1) { // gestion du mode de climatisation activé
        if (dataZones.temp.value < seuilBasModeCLIM) {
            dataZones.modeClimZone = 1;
        }
        else if (dataZones.temp.value > seuilHautModeCLIM) {
            dataZones.modeClimZone = 2;
        }
        else {
            if (indexPlannEteHiver == 1) {
                dataZones.modeClimZone = 1;
            }
            else if (indexPlannEteHiver == 2) {
                dataZones.modeClimZone = 2;
            }
            else {
                dataZones.modeClimZone = 0;
            }
        }
    }
    else {
        dataZones.modeClimZone = dataZones.statusMode.value;
    }

    // **************************** CONSIGNE **************************** //
    // On vérifie si la consigne doit être modulée en cas de non détéction de présence et uniquement pour le mode confort => réduction de la valeur de consigne
    let valueModulationConsigne = 0;
    if (dataZones.presence.timestamp > 0 && dataZones.presence.lastPresenceDetectedTimestamp > 0) { // si ces conditions ne sont pas remplies cela signifie pas de PIR préent ou problème de lecture d'info du PIR
        if (compareTimestamp(Date.now(), dataZones.presence.timestamp, 1440) === false) { // on applique la modulation que si le dernier message du PIR a moins de 24h sinon cela signifie un problème de communication
            // On applique la modulation de consigne lorsque qu'on détecte une absence, que le régime d'ambiance est "confort" et que la dernière détection de présence a plus d'une heure
            if (dataZones.presence.value == 0 && currentState == 0 && compareTimestamp(Date.now(), dataZones.presence.lastPresenceDetectedTimestamp, 60) === true) {
                valueModulationConsigne = 1;
                if (params.hasOwnProperty('valueModulationConsigne')) {
                    valueModulationConsigne = Number(params.valueModulationConsigne);
                }
                dataZones.consigneTorZone = Number(dataZones.consigneTorZone) - valueModulationConsigne;
                dataZones.consigneClimZone = Number(dataZones.consigneClimZone) - valueModulationConsigne;
            }
        }
    }

    // On définit la consigne
    dataZones.consigneTorZone = consignesArray[0][currentState] - valueModulationConsigne;
    if (actualMode == 1) { // mode Heat 
        dataZones.consigneClimZone = consignesArray[actualMode - 1][currentState] - valueModulationConsigne;
    } else if (actualMode == 2) { // mode Cool
        dataZones.consigneClimZone = consignesArray[actualMode - 1][currentState] + valueModulationConsigne;
    } else if (actualMode == 0 || actualMode == 3) { // mode Auto ou mode Fan
        if (indexPlannEteHiver == 1) {
            dataZones.consigneClimZone = consignesArray[0][currentState] - valueModulationConsigne;
        } else if (indexPlannEteHiver == 2) {
            dataZones.consigneClimZone = consignesArray[1][currentState] + valueModulationConsigne;
        } else if (dataZones.statusConsigne.value !== undefined || dataZones.statusConsigne.value !== null || dataZones.statusConsigne.value !== "") {
            dataZones.consigneClimZone = Number(dataZones.statusConsigne.value); // on applique pas valueModulationConsigne pour éviter une boucle qui baisse la température
        } else {
            dataZones.consigneClimZone = consignesArray[0][currentState] - valueModulationConsigne;
        }
    }

    // **************************** PILOTAGE **************************** //
    // On définit le pilotage
    if (forcageArretEvent == 1) { // si un event force l'arrêt on met tout à 0
        dataZones.pilotageTorZone = 0;
        dataZones.pilotageClimZone = 0;
    } else if (n(zones[x].allumageManuel) == 1) { // si allumage manuel on recopie le statusAllumage
        dataZones.pilotageTorZone = dataZones.statusAllumage.value;
        dataZones.pilotageClimZone = dataZones.statusAllumage.value;
    } else {
        if (n(zones[x].activationRegul) == 1) {
            // Calcul de pilotageTorZone
            if (indexPlannEteHiver == 1) {
                if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                    dataZones.pilotageTorZone = 0;
                }
                else if (dataZones.temp.value < consigneHorsGel) { // cas Hors-Gel
                    dataZones.pilotageTorZone = 1;
                }
                else if (n(zones[x].occupationPermanente) == 0) { // cas occupation intermintente
                    dataZones.pilotageTorZone = 0;
                }
                else if (currentState == 2) { // cas on est en absence
                    if (dataZones.temp.value >= (dataZones.consigneTorZone + (hysteresisRegulTOR / 2))) {
                        dataZones.pilotageTorZone = 0;
                    }
                    else if (dataZones.temp.value <= (dataZones.consigneTorZone - (hysteresisRegulTOR / 2))) {
                        dataZones.pilotageTorZone = 1;
                    }
                }
                else {
                    if (dataZones.temp.value >= (dataZones.consigneTorZone + (hysteresisRegulTOR / 2))) {
                        dataZones.pilotageTorZone = 0;
                    }
                    else if (dataZones.temp.value <= (dataZones.consigneTorZone - (hysteresisRegulTOR / 2))) {
                        dataZones.pilotageTorZone = 1;
                    }
                }
            } else {
                dataZones.pilotageTorZone = 0;
            }

            // Calcul de pilotageClimZone
            if (indexPlannEteHiver == 0) { // période d'intersaison on laisse éteint
                dataZones.pilotageClimZone = 0;
            } else if (actualMode == 1) { // Mode paramétré en chauffage
                if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                    dataZones.pilotageClimZone = 0;
                }
                else if (dataZones.temp.value < consigneHorsGel) { // cas Hors-Gel
                    dataZones.pilotageClimZone = 1;
                }
                else if (n(zones[x].occupationPermanente) == 0) { // cas occupation intermintente
                    dataZones.pilotageClimZone = 0;
                }
                else if (dataZones.temp.value >= (dataZones.consigneClimZone + hysteresisRegulCLIM)) { // cas pour éviter la ventialtion quand Temp largement dépassé
                    dataZones.pilotageClimZone = 0;
                }
                else if (currentState == 2 && dataZones.temp.value > dataZones.consigneClimZone) { // cas de l'absence
                    dataZones.pilotageClimZone = 0;
                }
                else {
                    dataZones.pilotageClimZone = 1;
                }
            } else if (actualMode == 2) { // Mode paramétré en clim
                if (tempext < tempNonClim && params.activTempNonClim == 1) {
                    dataZones.pilotageClimZone = 0;
                }
                else if (n(zones[x].occupationPermanente) == 0) { // cas occupation intermintente
                    dataZones.pilotageClimZone = 0;
                }
                else if (dataZones.temp.value <= (dataZones.consigneClimZone - hysteresisRegulCLIM)) { // cas pour éviter la ventialtion quand Temp largement dépassé
                    dataZones.pilotageClimZone = 0;
                }
                else if (currentState == 2 && dataZones.temp.value < dataZones.consigneClimZone) { // cas de l'absence
                    dataZones.pilotageClimZone = 0;
                }
                else {
                    dataZones.pilotageClimZone = 1;
                }
            } else { //si actualMode == 0 (Auto) ou actualMode == 3 (Fan)
                if (indexPlannEteHiver == 1) { // période de chauffage
                    if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (dataZones.temp.value < consigneHorsGel) { // cas Hors-Gel
                        dataZones.pilotageClimZone = 1;
                    }
                    else if (n(zones[x].occupationPermanente) == 0) { // cas occupation intermintente
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (dataZones.temp.value >= (dataZones.consigneClimZone + hysteresisRegulCLIM)) { // cas pour éviter la ventialtion quand Temp largement dépassé
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (currentState == 2 && dataZones.temp.value > dataZones.consigneClimZone) { // cas de l'absence
                        dataZones.pilotageClimZone = 0;
                    }
                    else {
                        dataZones.pilotageClimZone = 1;
                    }
                } else if (indexPlannEteHiver == 2) { // période de clim
                    if (tempext < tempNonClim && params.activTempNonClim == 1) {
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (n(zones[x].occupationPermanente) == 0) { // cas occupation intermintente
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (dataZones.temp.value <= (dataZones.consigneClimZone - hysteresisRegulCLIM)) { // cas pour éviter la ventialtion quand Temp largement dépassé
                        dataZones.pilotageClimZone = 0;
                    }
                    else if (currentState == 2 && dataZones.temp.value < dataZones.consigneClimZone) { // cas de l'absence
                        dataZones.pilotageClimZone = 0;
                    }
                    else {
                        dataZones.pilotageClimZone = 1;
                    }
                } else {
                    dataZones.pilotageClimZone = 0;
                }
            }

        } else {// si regul désactivé on recopie le statusAllumage
            dataZones.pilotageTorZone = dataZones.statusAllumage.value;
            dataZones.pilotageClimZone = dataZones.statusAllumage.value;
        }
    }

    // On mémorise quelques infos utiles pour le debug
    dataZones.etatAmbiance = currentState;       // 0/1/2 -> Confort/Réduit/Absence
    dataZones._saisonIndex = indexPlannEteHiver; // 0/1/2 -> Intersaison/Chauffage/Clim
    // puis :
    zones[x].data = dataZones;
}

// Fonction pour parser un planning
function parseSchedule(schedule, dayOffset = 0) {
    let events = [];
    if (!schedule || typeof schedule !== "string") {
        return events;
    }

    let parts = schedule.split(";"); // Divise la chaîne en morceaux
    for (let z = 0; z < parts.length; z++) {
        let match = parts[z].trim().match(/(\d{1,2}):(\d{2})\s+\((\d)\)/); // Extrait l'heure et l'état
        if (match) {
            let hours = parseInt(match[1], 10);
            let minutes = parseInt(match[2], 10);
            let state = parseInt(match[3], 10);
            let timeInMinutes = hours * 60 + minutes + (dayOffset * 24 * 60);
            events.push({ time: timeInMinutes, state });
        }
    }
    return events;
}

// Fonction pour vérifier si un événement est en cours
function isEventActive(event, now) {
    let start = new Date(event.startDate);
    let end = new Date(event.endDate);
    return now >= start && now < end;
}

// Fonction qui compare 2 timestamp et renvoie true si la diff entre timestamp1 et timestamp2 est supp à intervalle
function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2); // Différence en millisecondes
    const intervallInMilliseconds = intervalle * 60 * 1000; // intervalle en millisecondes
    if (differenceInMilliseconds > intervallInMilliseconds) {
        return true;
    }
    return false;
}

// Fonction qui détermine si on est en période de chauffage, de climatisation ou d'intersaison
function determinerPeriode(parameters) {
    // Obtenir la date actuelle
    let dateActuelle = new Date();
    let jourActuel = dateActuelle.getDate();
    let moisActuel = dateActuelle.getMonth() + 1; // Les mois sont indexés à partir de 0
    let index = 0;

    // Convertir les périodes en objets Date pour faciliter la comparaison
    let [jourDebutChauffe, moisDebutChauffe] = parameters.startPeriodChauffe.split('-').map(Number);
    let [jourFinChauffe, moisFinChauffe] = parameters.endPeriodChauffe.split('-').map(Number);
    let [jourDebutClim, moisDebutClim] = parameters.startPeriodClim.split('-').map(Number);
    let [jourFinClim, moisFinClim] = parameters.endPeriodClim.split('-').map(Number);

    // Fonction pour comparer les dates
    function estDansPeriode(jourDebut, moisDebut, jourFin, moisFin) {
        if (moisDebut < moisFin) {
            if (moisActuel > moisDebut && moisActuel < moisFin) {
                return true;
            }
            else if (moisActuel === moisDebut && jourActuel >= jourDebut) {
                return true;
            }
            else if (moisActuel === moisFin && jourActuel <= jourFin) {
                return true;
            }
        }
        else if (moisDebut > moisFin) {
            if (moisActuel > moisDebut || moisActuel < moisFin) {
                return true;
            }
            else if (moisActuel === moisDebut && jourActuel >= jourDebut) {
                return true;
            }
            else if (moisActuel === moisFin && jourActuel <= jourFin) {
                return true;
            }
        }
        else if (moisDebut === moisFin) {
            if (moisActuel === moisDebut && jourActuel >= jourDebut && jourActuel <= jourFin) {
                return true;
            }
        }
        return false;
    }

    // Vérifier les périodes
    if (estDansPeriode(jourDebutChauffe, moisDebutChauffe, jourFinChauffe, moisFinChauffe)) {
        index = 1;
    }
    if (estDansPeriode(jourDebutClim, moisDebutClim, jourFinClim, moisFinClim)) {
        index = 2;
    }
    return index;
}

// --------- ÉQUIVALENCES (LÉGENDE) ----------
const MAP = {
    etatAmbiance: { 0: "Confort", 1: "Réduit", 2: "Absence" },
    eventValue: { 0: "Auto", 1: "Confort", 2: "Réduit", 3: "Absence", 4: "Arrêt (forcer OFF)" },
    modeClim: { 0: "Auto", 1: "Heat (Chaud)", 2: "Cool (Froid)", 3: "Fan (Ventilation)" },
    pilotage: { 0: "Off", 1: "On" },
    saison: { 0: "Intersaison", 1: "Période Chauffage", 2: "Période Climatisation" },
    presence: { 0: "Absence", 1: "Présence" }
};

function label(map, v) {
    if (!map) return "N/A";
    return Object.prototype.hasOwnProperty.call(map, v) ? map[v] : "N/A";
}


function keepZone(z, i) {
    const mode = (ZONES_DEBUG.by || "").toLowerCase();
    const values = Array.isArray(ZONES_DEBUG.values) ? ZONES_DEBUG.values : null;
    const rx = ZONES_DEBUG.regex ? new RegExp(ZONES_DEBUG.regex, "i") : null;

    switch (mode) {
        case "numero":
            return values ? values.indexOf(Number(z.numero)) !== -1 : true;
        case "planningid":
            return values ? values.indexOf(Number(z.planningId)) !== -1 : true;
        case "nom":
            if (rx) return rx.test(String(z.nom || ""));
            if (values) {
                const name = String(z.nom || "");
                for (let k = 0; k < values.length; k++) {
                    if (String(values[k]) === name) return true;
                }
                return false;
            }
            return true;
        case "index":
            return values ? values.indexOf(i) !== -1 : true;
        default:
            return true;
    }
}

// --------- EXPORT / DEBUG (avec interrupteur) ----------

// Filtre des zones (comme avant)
const zonesToShow = zones.filter(keepZone);
const _zonesForOutput = zonesToShow.length ? zonesToShow : zones;

// On conserve toujours toutes les zones en global
global.set("zones", zones);

// Helpers d'affichage
function fmt(v) {
    return (v === undefined || v === null) ? "N/A" : String(v);
}
function lab(map, v) {
    if (!map) return "N/A";
    return Object.prototype.hasOwnProperty.call(map, v) ? map[v] : "N/A";
}
function numOrNA(v) {
    return (typeof v === "number" && !isNaN(v)) ? v : "N/A";
}

// On récupère les hystérésis depuis params (déclaré en haut du node)
const hClim = Number(params && params.hysteresisRegulCLIM != null ? params.hysteresisRegulCLIM : 0);
const hTor  = Number(params && params.hysteresisRegulTOR  != null ? params.hysteresisRegulTOR  : 0);

if (DEBUG_ENABLED) {
    // Légende une seule fois
    node.warn(
        "==== RÉSUMÉ ZONES ====  |  " +
        "Etat ambiance: 0=Confort,1=Réduit,2=Absence  |  " +
        "Mode: 0=Auto,1=Heat,2=Cool,3=Fan  |  " +
        "Pilotage: 0=Off,1=On  |  " +
        "Saison: 0=Inter,1=Chauff,2=Clim"
    );
    node.warn(
        "Seuils numériques : CLIM = consigneClim ± hClim(" + hClim +
        "), TOR = consigneTor ± hTor/2(" + (hTor/2) + ")"
    );

    // 1 seul warn par zone (multi-lignes pour lisibilité)
    for (let i = 0; i < _zonesForOutput.length; i++) {
        const zone = _zonesForOutput[i];
        const d = (zone && zone.data) ? zone.data : {};

        const tempValue = (d.temp && d.temp.value !== undefined && d.temp.value !== null)
            ? d.temp.value
            : "N/A";

        // ► Conversions numériques
        const consigneClimNum = Number(d.consigneClimZone);
        const consigneTorNum  = Number(d.consigneTorZone);
        const tempNum         = Number(tempValue);

        // Seuils avec hystérésis
        const climHi = consigneClimNum + hClim;
        const climLo = consigneClimNum - hClim;
        const torHi  = consigneTorNum  + (hTor / 2);
        const torLo  = consigneTorNum  - (hTor / 2);

        const planningId = (zone && zone.planningId !== undefined && zone.planningId !== null)
            ? zone.planningId
            : "N/A";

        // On force aussi un cast numérique sur le pilotage TOR pour vérifier
        const pilotageTorBrut = d.pilotageTorZone;
        const pilotageTorNum  = Number(pilotageTorBrut);

        const pilotageClimBrut = d.pilotageClimZone;
        const pilotageClimNum  = Number(pilotageClimBrut);

        const line = [
            "Zone " + fmt((zone.numero !== undefined && zone.numero !== null) ? zone.numero : i) +
            " - " + fmt((zone.nom !== undefined && zone.nom !== null) ? zone.nom : "Sans nom"),
            "  planningId: " + fmt(planningId),
            "  Saison: " + fmt(d._saisonIndex) + " (" + lab(MAP.saison, d._saisonIndex) + ")" +
            " | Ambiance: " + fmt(d.etatAmbiance) + " (" + lab(MAP.etatAmbiance, d.etatAmbiance) + ")" +
            " | Mode: " + fmt(d.modeClimZone) + " (" + lab(MAP.modeClim, d.modeClimZone) + ")",

            // CLIM
            "  CLIM -> Consigne brut=" + fmt(d.consigneClimZone) +
            " num=" + numOrNA(consigneClimNum) +
            " | Seuils: [" + numOrNA(climLo) + " ; " + numOrNA(climHi) + "]" +
            " | Pilotage brut=" + fmt(pilotageClimBrut) +
            " num=" + numOrNA(pilotageClimNum) +
            " type=" + (pilotageClimBrut === undefined ? "undefined" : typeof pilotageClimBrut) +
            " (" + lab(MAP.pilotage, d.pilotageClimZone) + ")",

            // TOR (ce que tu voulais voir clairement)
            "  TOR  -> Consigne brut=" + fmt(d.consigneTorZone) +
            " num=" + numOrNA(consigneTorNum) +
            " | Seuils: [" + numOrNA(torLo) + " ; " + numOrNA(torHi) + "]" +
            " | Pilotage brut=" + fmt(pilotageTorBrut) +
            " num=" + numOrNA(pilotageTorNum) +
            " type=" + (pilotageTorBrut === undefined ? "undefined" : typeof pilotageTorBrut) +
            " (" + lab(MAP.pilotage, d.pilotageTorZone) + ")",

            "  Temp: brut=" + fmt(tempValue) +
            " num=" + (isNaN(tempNum) ? "N/A" : tempNum)
        ].join("\n");

        node.warn(line);
    }
}
